def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    truck_patches = image_patch.find("truck")
    cinzano_patches = image_patch.find("cinzano")

    if not truck_patches:
        return image_patch  # Return the entire image if no truck is found
    if not cinzano_patches:
        return truck_patches[0]  # Return the first truck found if no cinzano is found

    # Sort truck patches by depth to find the one in the front
    truck_patches.sort(key=lambda t: t.compute_depth())
    front_truck = truck_patches[-1]

    # Check if cinzano is on the truck
    for patch in cinzano_patches:
        if front_truck.overlaps_with(patch.left, patch.lower, patch.right, patch.upper):
            return front_truck

    return front_truck  # Return the front truck if cinzano is not found on it

