def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    vehicle_patches = image_patch.find("vehicle")
    yellow_vehicle_patches = [v for v in vehicle_patches if v.verify_property("vehicle", "yellow")]

    if len(yellow_vehicle_patches) == 0:
        return image_patch

    man_patches = image_patch.find("man")
    tire_patches = image_patch.find("tire")

    if len(man_patches) != 1 or len(tire_patches) < 1:
        return yellow_vehicle_patches[0]

    min_distance = float('inf')
    closest_tire_patch = None

    for tire_patch in tire_patches:
        for man_patch in man_patches:
            dist = distance(tire_patch, man_patch)
            if dist < min_distance:
                min_distance = dist
                closest_tire_patch = tire_patch

    for vehicle_patch in yellow_vehicle_patches:
        if vehicle_patch.overlaps_with(closest_tire_patch.left, closest_tire_patch.lower, closest_tire_patch.right, closest_tire_patch.upper):
            return vehicle_patch

    return yellow_vehicle_patches[0]

