def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    zebra_patches = image_patch.find("zebra")
    sunbeam_patches = image_patch.find("sunbeam")

    if not zebra_patches:
        return image_patch
    if not sunbeam_patches:
        return zebra_patches[0]

    zebra_center = sum([p.horizontal_center for p in zebra_patches]) / len(zebra_patches)
    sunbeam_center = sum([p.horizontal_center for p in sunbeam_patches]) / len(sunbeam_patches)

    if abs(zebra_center - sunbeam_center) < max(max([p.width for p in zebra_patches]), max([p.width for p in sunbeam_patches])) / 2:
        for zebra in zebra_patches:
            if zebra.overlaps_with(sunbeam_patches[0].left, sunbeam_patches[0].lower, sunbeam_patches[0].right, sunbeam_patches[0].upper):
                return zebra

    return zebra_patches[0]

