        return image_patch

    cake_depths = [patch.compute_depth() for patch in cake_patches]
    plate_depths = [patch.compute_depth() for patch in plate_patches]

    cake_on_side = [cake for cake in cake_patches if abs(cake.vertical_center - cake.image.height / 2) < cake.width / 4]

    cake_in_front_of_plate = []
    for cake in cake_on_side:
