                cake_in_front_of_plate.append((cake, plate))
                break

    if not cake_in_front_of_plate:
        return cake_patches[0]

    cake_in_front_of_plate.sort(key=lambda x: x[0].horizontal_center)
    return cake_in_front_of_plate[0][0]

